// Acceptance feedback: a large OU must not fill navigation with account objects.
const {chromium}=require('playwright'),fs=require('fs'),os=require('os'),path=require('path'),http=require('http'),assert=require('assert/strict'),{execFileSync}=require('child_process');
const repo=path.resolve(__dirname,'../..'),dir=fs.mkdtempSync(path.join(os.tmpdir(),'sambaadm-navigation-'));
execFileSync('go',['test','./internal/web','-run','^TestWorkspaceBrowserFixtures$','-count=1'],{cwd:repo,env:{...process.env,SAMBAADM_WEB_FIXTURE_DIR:dir}});
const base='DC=example,DC=com',people='OU=People,'+base,empty='OU=Empty,'+base;const errors=[];
const users=Array.from({length:500},(_,i)=>({samAccountName:'user'+String(i).padStart(4,'0'),displayName:'User '+i,mail:'user'+i+'@example.com',department:i%2?'IT':'Finance',enabled:i%2===0,dn:'CN=User'+i+','+people}));
const groups=users.map((u,i)=>({samAccountName:'group'+i,dn:'CN=Group'+i+','+people,members:[]})),computers=users.map((u,i)=>({samAccountName:'PC'+i+'$',dn:'CN=PC'+i+','+people,dnsHostName:'pc'+i+'.example.com'}));
const data={users,groups,computers,ou:[{name:'People',dn:people},{name:'Empty',dn:empty}]};
function tree(kind){return {dn:base,label:'example.com',kind:'domain',children:[{dn:people,label:'People',kind:'ou',children:(data[kind]||users).filter(x=>x.dn.endsWith(','+people)).map(x=>({dn:x.dn,objectDN:x.dn,parentDN:people,label:x.samAccountName,kind:{users:'user',groups:'group',computers:'computer'}[kind]||'ou',children:[]}))},{dn:empty,label:'Empty',kind:'ou',children:[]}]};}
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://localhost').pathname,file=p.startsWith('/static/')?path.join(repo,'internal/web',p):path.join(dir,'admin-'+p.slice(1)+'.html');if(!fs.existsSync(file)){res.writeHead(404).end();return;}res.setHeader('Content-Type',file.endsWith('.js')?'application/javascript':file.endsWith('.css')?'text/css':'text/html');res.end(fs.readFileSync(file));});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true});try{const page=await browser.newPage({viewport:{width:1440,height:1000}});page.on('pageerror',e=>errors.push(e.message));await page.route('**/api/v1/**',async route=>{const url=new URL(route.request().url());await route.fulfill({json:url.pathname.endsWith('/directory/tree')?tree(url.searchParams.get('kind')):data[url.pathname.split('/').at(-1)]||[]});});
async function visit(name){await page.goto('http://127.0.0.1:'+server.address().port+'/'+name);await page.getByRole('status').filter({hasText:'Данные обновлены'}).waitFor();}
for(const name of ['users','groups','computers','ou']){await visit(name);const nav=page.getByRole('complementary',{name:'Навигация раздела'});assert.equal(await nav.locator('.directory-tree button').count(),3,name+' must show only domain and two OUs');assert.equal(await nav.getByRole('button',{name:/^(user\d|group\d|PC\d)/}).count(),0);assert.equal(await page.locator('tbody tr').count(),name==='ou'?2:500);await nav.getByRole('button',{name:'People',exact:true}).click();assert.equal(await page.locator('tbody tr').count(),name==='ou'?1:500);}
await visit('users');await page.getByText('Фильтры по колонкам',{exact:true}).click();await page.getByLabel('Фильтр Состояние',{exact:true}).selectOption('false');assert.equal(await page.locator('tbody tr').count(),250);await page.getByLabel('Фильтр Логин',{exact:true}).fill('user001');assert.equal(await page.locator('tbody tr').count(),5);await page.getByLabel('Фильтр DN',{exact:true}).fill('absent');assert.equal(await page.locator('tbody tr').innerText(),'Объекты не найдены');await page.getByRole('button',{name:'Сбросить фильтры',exact:true}).click();assert.equal(await page.locator('tbody tr').count(),500);
assert.equal(await page.locator('thead [data-column=mail]').isVisible(),false);await page.getByText('Колонки',{exact:true}).click();await page.getByLabel('Показывать колонку Почта',{exact:true}).check();assert.ok(await page.locator('tbody [data-column=mail]').first().isVisible());await page.getByLabel('Показывать колонку DN',{exact:true}).uncheck();assert.equal(await page.locator('thead [data-column="dn"]').isVisible(),false);assert.equal(await page.locator('tbody [data-column="dn"]:visible').count(),0);await page.reload();await page.getByRole('status').filter({hasText:'Данные обновлены'}).waitFor();assert.equal(await page.locator('thead [data-column="dn"]').isVisible(),false);await page.getByText('Колонки',{exact:true}).click();await page.getByRole('button',{name:'Все колонки',exact:true}).click();assert.ok(await page.locator('thead [data-column="dn"]').isVisible());assert.ok((await page.locator('tbody [data-column="dn"]').first().boundingBox()).width>=320);assert.ok(await page.locator('.workspace-table').evaluate(e=>e.scrollWidth>e.clientWidth));
await page.getByRole('complementary').getByRole('button',{name:'Empty',exact:true}).click();assert.equal(await page.locator('tbody tr').innerText(),'Объекты не найдены');await page.getByRole('button',{name:'Все объекты',exact:true}).click();await page.getByLabel('Поиск в текущем списке',{exact:true}).fill('user0013');assert.equal(await page.locator('tbody tr').count(),1);assert.ok((await page.locator('tbody').innerText()).includes('user0013'));
await page.screenshot({path:path.join(dir,'folders-and-filters.png'),fullPage:true});await page.setViewportSize({width:390,height:844});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));assert.deepEqual(errors,[]);console.log('PASS: folder-only users/groups/computers/OU navigation with 500 accounts; right-pane access, state/column/search filters, empty OU, persistent columns and mobile');console.log('Screenshots:',dir);
}finally{await browser.close();server.close();}})().catch(e=>{console.error(e);server.close();process.exitCode=1;});
